fn prime_divisors(n: Int) -> Tuple<Int, Int, Option<Int>> {
    let mut sum = 0
    let mut max = None
    for i in range(2, n + 1) {
        if n % i == 0 && is_prime(i) {
            sum += i
            max = Some(i)
        }
    }
    (sum, max.unwrap_or(-1), max)
}
